def inline(s):
 s=html.escape(s)
 s=re.sub(r'\[([^\]]+)\]\(([^)]+)\)',lambda m:f'<a href="{m[2].replace(".md", ".html")}">{m[1]}</a>',s)
 s=re.sub(r'`([^`]+)`',r'<code>\1</code>',s)
 s=re.sub(r'\*\*([^*]+)\*\*',r'<strong>\1</strong>',s)
 return s
def markdown(md):
 lines=md.splitlines();out=[];i=0
 while i<len(lines):
  l=lines[i]
  if not l.strip():i+=1;continue
  if l.startswith('```'):
   buf=[];i+=1
   while i<len(lines) and not lines[i].startswith('```'):buf.append(lines[i]);i+=1
   out.append('<pre><code>'+html.escape('\n'.join(buf))+'</code></pre>');i+=1;continue
  if l.startswith('#'):
   level=len(l)-len(l.lstrip('#'));out.append(f'<h{level}>'+inline(l[level:].strip())+f'</h{level}>');i+=1;continue
  if l.startswith('|'):
   rows=[]
   while i<len(lines) and lines[i].startswith('|'):
    vals=[x.strip() for x in lines[i].strip('|').split('|')]
    if not all(re.fullmatch(r'[:\- ]+',x or '-') for x in vals):rows.append(vals)
    i+=1
   out.append('<div class="table-wrap"><table>'+''.join('<tr>'+''.join(f'<{"th" if n==0 else "td"}>'+inline(v)+f'</{"th" if n==0 else "td"}>' for v in row)+'</tr>' for n,row in enumerate(rows))+'</table></div>');continue
  if re.match(r'^(\d+\. |\- )',l):
   ordered=bool(re.match(r'^\d+\. ',l));tag='ol' if ordered else 'ul';buf=[]
   while i<len(lines) and re.match(r'^(\d+\. |\- )',lines[i]):buf.append('<li>'+inline(re.sub(r'^(\d+\. |\- )','',lines[i]))+'</li>');i+=1
   out.append('<'+tag+'>'+''.join(buf)+'</'+tag+'>');continue
  buf=[l];i+=1
  while i<len(lines) and lines[i].strip() and not re.match(r'^[#|]|^```|^\d+\. ',lines[i]):buf.append(lines[i]);i+=1
  out.append('<p>'+inline(' '.join(buf))+'</p>')
 return '\n'.join(out)
